"""Splitting money between parties."""

from collections.abc import Sequence


def _plain_split(total: int, weights: Sequence[int]) -> list[int]:
    weight_sum = sum(weights)
    shares = [total * w // weight_sum for w in weights]
    remainders = [total * w % weight_sum for w in weights]
    leftover = total - sum(shares)
    # sorted() is stable, so equal remainders keep their original order
    order = sorted(range(len(weights)), key=lambda i: -remainders[i])
    for i in order[:leftover]:
        shares[i] += 1
    return shares


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if len(weights) == 0:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if sum(weights) == 0:
        raise ValueError("weights must not add up to zero")
    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(c < 0 for c in caps):
            raise ValueError("caps must not be negative")
        if sum(c for c, w in zip(caps, weights) if w > 0) < total:
            raise ValueError("caps of the weighted parties cannot hold total")

    result = [0] * len(weights)
    active = [i for i, w in enumerate(weights) if w > 0]
    remaining = total

    if caps is None:
        for i, share in zip(active, _plain_split(remaining, [weights[i] for i in active])):
            result[i] = share
        return result

    while True:
        shares = _plain_split(remaining, [weights[i] for i in active])
        over = [i for i, share in zip(active, shares) if share > caps[i]]
        if not over:
            for i, share in zip(active, shares):
                result[i] = share
            return result
        for i in over:
            result[i] = caps[i]
            remaining -= caps[i]
        active = [i for i in active if i not in over]
